# Function to calculate the nth Rencontres number (binomial coefficient C(n+m-1, m))
def calculate_combination(n, m):
    if m == 0 or m == n:
        return 1
    else:
        # Use dynamic programming to store intermediate results
        combination_table = [[0 for _ in range(m+1)] for _ in range(n+1)]

        for i in range(n+1):
            for j in range(min(i, m)+1):
                if j == 0:
                    combination_table[i][j] = 1
                else:
                    combination_table[i][j] = combination_table[i-1][j] + combination_table[i-1][j-1]

        return combination_table[n][m]

# Function to calculate the nth Rencontres number using the formula n * M!(n-m) / ((n-m)! * M! * m!)
def rencontres_number(n, m):
    numerator = calculate_combination(n + m - 1, m)
    denominator = (calculate_combination(n - m, m) * factorial(m)) ** 2
    return numerator // denominator

